function createEmitter() {
  const handlers = {};
  return {
    on(name, fn) {
      if (!handlers[name]) {
        handlers[name] = [];
      }
      handlers[name].push(fn);
    },
    emit(name, data) {
      for (const fn of handlers[name] || []) {
        fn(data);
      }
    }
  };
}

