function buildUrl(base, params) {
  const pairs = Object.entries(params).map(([k, v]) => k + "=" + encodeURIComponent(v));
  if (pairs.length === 0) {
    return base;
  }
  return base + "?" + pairs.join("&");
}

function statusKind(code) {
  if (code >= 200 && code < 300) {
    return "ok";
  }
  if (code >= 400 && code < 500) {
    return "client error";
  }
  if (code >= 500 && code < 600) {
    return "server error";
  }
  return "other";
}

