class ScoreTracker {
  constructor() {
    this.scores = new Map();
  }
  add(name, points) {
    this.scores.set(name, (this.scores.get(name) || 0) + points);
  }
  total(name) {
    return this.scores.get(name) || 0;
  }
  leader() {
    let best = null;
    let bestScore = -Infinity;
    for (const [name, score] of this.scores) {
      if (score > bestScore) {
        best = name;
        bestScore = score;
      }
    }
    return best;
  }
}
